mapper.select:
SELECT 
FROM erp_bookstore_schedule_exception
WHERE center_code = #{centerCode}
  AND exception_type <> 'SLOT_CHANGE'
  AND start_date <= #{endDate}
  AND end_date   >= #{startDate}
ORDER BY start_date ASC

SELECT 
FROM erp_bookstore_schedule_exception
WHERE center_code = #{centerCode}
  AND exception_type = 'SLOT_CHANGE'
  AND start_date = #{targetDate}

SELECT
    ,
    CASE WHEN end_date < CAST(DATEADD(HOUR, 9, GETUTCDATE()) AS DATE) THEN 1 ELSE 0 END AS past
FROM erp_bookstore_schedule_exception
WHERE center_code = #{centerCode}
  AND exception_id = #{exceptionId}

mapper.delete:
DELETE FROM erp_bookstore_schedule_exception
WHERE center_code = #{centerCode}
  AND exception_id = #{exceptionId}
